<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="System Settings" />
    <FilterTabsNav :items="tabs" variant="underline" />
    <AppLoader v-if="isLoading && !settings" subject="settings" variant="inline" />
    <AppError v-else-if="error && !settings" :error="error" title="Failed to load settings" variant="table" />
    <NuxtPage v-else-if="settings" :settings="settings" />
  </section>
</template>

<script setup lang="ts">
import { getAllSystemSettings } from '~/client';
import type { NavigationItem } from '~/types/projects/navigation';

definePageMeta({
  roles: ['admin'],
});

useHead({
  title: 'System Settings',
});

const route = useRoute();

const {
  data: settings,
  error,
  isLoading,
} = useQuery({
  key: () => ['system-settings'],
  query: () => getAllSystemSettings({ composable: '$fetch' }),
});

const tabs = computed<NavigationItem[]>(() => [
  {
    label: 'General',
    to: { name: 'system-settings-recruitment' },
    selected: route.name === 'system-settings-recruitment',
  },
  {
    label: 'Project Recruitment',
    to: { name: 'system-settings-recruitment-project-recruitment' },
    selected: route.name === 'system-settings-recruitment-project-recruitment',
  },
  {
    label: 'Urgency Presets',
    to: { name: 'system-settings-recruitment-urgency' },
    selected: route.name === 'system-settings-recruitment-urgency',
  },
  {
    label: 'Throttling',
    to: { name: 'system-settings-recruitment-throttling' },
    selected: route.name === 'system-settings-recruitment-throttling',
  },
  {
    label: 'Analytics',
    to: { name: 'system-settings-recruitment-analytics' },
    selected: route.name === 'system-settings-recruitment-analytics',
  },
  {
    label: 'Prompt',
    to: { name: 'system-settings-recruitment-prompt' },
    selected: route.name === 'system-settings-recruitment-prompt',
  },
]);
</script>
